/**
 * Expo config plugin: disable ENABLE_USER_SCRIPT_SANDBOXING on iOS.
 *
 * Xcode 15+ defaults ENABLE_USER_SCRIPT_SANDBOXING=YES, which blocks React
 * Native's build-time scripts (e.g. "[CP] Copy Pods Resources",
 * "Bundle React Native code and images") from writing files like
 *   .../Pods/resources-to-copy-Momento.txt
 * Build fails with:
 *   error: Sandbox: bash(NNNN) deny(1) file-write-create ...
 *
 * This plugin edits the Podfile generated by `expo prebuild` to add a
 * post_install hook that flips the flag to NO for every target (Pods project
 * + the user Xcode project). Running `pod install` applies it to both
 * Pods.xcodeproj and Momento.xcodeproj.
 *
 * Why a config plugin instead of just editing Podfile directly?
 * `ios/` is gitignored for Expo managed projects, so a hand-edited Podfile is
 * wiped on the next `expo prebuild`. This plugin re-applies the change every
 * time prebuild regenerates the Podfile — including on EAS cloud builds.
 */

const { withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

const SANDBOX_MARKER = '# @momento:disable-script-sandboxing';

const SANDBOX_SNIPPET = `
    ${SANDBOX_MARKER}
    # Xcode 15+ sandboxes build scripts by default, which breaks React Native's
    # Copy Pods Resources and Bundle React Native code phases. See
    # apps/mobile/plugins/with-ios-script-sandboxing.js for details.
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        build_config.build_settings['ENABLE_USER_SCRIPT_SANDBOXING'] = 'NO'
      end
    end
    installer.aggregate_targets.each do |agg_target|
      agg_target.user_project.native_targets.each do |native_target|
        native_target.build_configurations.each do |build_config|
          build_config.build_settings['ENABLE_USER_SCRIPT_SANDBOXING'] = 'NO'
        end
      end
      agg_target.user_project.save
    end
`;

function injectIntoPodfile(contents) {
  if (contents.includes(SANDBOX_MARKER)) {
    return contents;
  }

  // Insert the snippet just before the closing `end` of the `post_install do`
  // block. We match the react_native_post_install(...) call and insert right
  // after its closing paren.
  const match = contents.match(
    /(react_native_post_install\([\s\S]*?\n\s*\))/,
  );
  if (!match) {
    // Expo changed the post_install template — log and no-op rather than
    // silently producing a broken Podfile.
    console.warn(
      '[with-ios-script-sandboxing] Could not locate react_native_post_install() in Podfile; skipping.',
    );
    return contents;
  }

  return contents.replace(match[1], `${match[1]}\n${SANDBOX_SNIPPET}`);
}

module.exports = function withIosScriptSandboxing(config) {
  return withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const podfilePath = path.join(
        cfg.modRequest.platformProjectRoot,
        'Podfile',
      );
      if (!fs.existsSync(podfilePath)) {
        // No iOS project yet — nothing to edit.
        return cfg;
      }
      const before = fs.readFileSync(podfilePath, 'utf8');
      const after = injectIntoPodfile(before);
      if (after !== before) {
        fs.writeFileSync(podfilePath, after);
      }
      return cfg;
    },
  ]);
};
